// ======================================================
// ENFORCED RESEARCH OUTPUT VALIDATOR
// Purpose:
// - Validate the Social Web Agent research output
// - Prevent empty/invalid research from continuing
// - Preserve valid agent output exactly
// - Generate a deterministic empty research package
//   when no verifiable research was produced
// ======================================================

const agentOutput = $json.output || {};

const knowledge = agentOutput.knowledge || {};

const sources = Array.isArray(agentOutput.sources)
  ? agentOutput.sources
  : [];

// ======================================================
// Detect whether meaningful research exists
// ======================================================

const hasVerifiedFacts =
  Array.isArray(knowledge.verified_facts) &&
  knowledge.verified_facts.length > 0;

const hasSources =
  sources.length > 0;

const hasRealData =
  hasVerifiedFacts || hasSources;

// ======================================================
// VALID RESEARCH
// ======================================================

if (hasRealData) {
  return [
    {
      json: $json
    }
  ];
}

// ======================================================
// RECOVER ORIGINAL REQUEST CONTEXT
// ======================================================

const requestItem =
  $("When Executed by Another Workflow").first()?.json || {};

const business =
  requestItem.business || {};

const content =
  requestItem.content || {};

// ======================================================
// Determine research topic
// Priority:
// 1. Original content.topic
// 2. Agent query_topic
// 3. Safe fallback
// ======================================================

const query =
  content.topic ||
  agentOutput.query_topic ||
  "Unknown topic";

// ======================================================
// DETERMINISTIC EMPTY RESEARCH PACKAGE
// ======================================================

return [
  {
    json: {
      output: {
        query_topic: String(query),

        execution_timestamp:
          new Date().toISOString(),

        metadata: {
          research_scope: "mixed",
          recent_updates_found: false,
          overall_confidence: "Low"
        },

        knowledge: {
          executive_summary:
            "No verifiable information could be retrieved.",

          key_findings: [],

          verified_facts: [],

          core_concepts: [],

          important_entities: [],

          major_developments: [],

          practical_implications: [],

          statistics: [],

          expert_insights: [],

          future_outlook: [],

          risks_or_limitations: [],

          common_questions: []
        },

        sources: []
      },

      _enforced_empty: true
    }
  }
];
